/* ------------------------------------------------------------------ */
/*  Constants, deterministic PRNG (Mulberry32, seed 42), helpers       */
/* ------------------------------------------------------------------ */
var DURATION = 8.000;
var SEED = 42;
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var rand = mulberry32(SEED);                 // used ONLY during deterministic build (init)
function rrange(a, b) { return a + (b - a) * rand(); }
function clamp(x, a, b) { return x < a ? a : (x > b ? b : x); }
function smooth(a, b, x) { var t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); }
function lerp(a, b, t) { return a + (b - a) * t; }

/* Key timeline moments (seconds of simTime) */
var T_CONTACT = 1.0, T_PUNCT = 1.06, T_EXIT = 3.8;

/* Balloon (teardrop) parameters */
var BAL_RY = 1.5, BAL_RS = 1.35, BAL_M = 0.7;
var Y_IMP = -0.2;                                   // impact height
var THETA_IMP = Math.acos(Y_IMP / BAL_RY);          // polar angle of impact
function profileR(theta) {
  return BAL_RS * Math.sin(theta) * Math.pow(Math.max(Math.sin(theta * 0.5), 1e-6), BAL_M);
}
var XR = profileR(THETA_IMP);                       // right (entry) surface x
var XL = -XR;                                       // left (exit) surface x
var DIAM = XR - XL;

/* Bullet kinematics: constant approach speed, exponential deceleration in water, constant after exit */
var V_APPROACH = 4.2, DECEL = 5.0, T_IN = T_EXIT - T_CONTACT;
var V_FLOOR = (DIAM - V_APPROACH * (1 - Math.exp(-DECEL * T_IN)) / DECEL) / T_IN;
function bulletTipX(t) {
  if (t <= T_CONTACT) return XR + V_APPROACH * (T_CONTACT - t);
  if (t <= T_EXIT) {
    var s = t - T_CONTACT;
    return XR - (V_APPROACH * (1 - Math.exp(-DECEL * s)) / DECEL + V_FLOOR * s);
  }
  return XL - V_FLOOR * (t - T_EXIT);
}
var BULLET_LEN = 0.66;

/* Water-mass deformation schedule (shared by shaders' uniforms and particle emitters) */
var G_MASS = 0.1;
function fallAt(t) { var s = Math.max(0, t - 1.55); return 0.5 * G_MASS * s * s; }
function slumpAt(t) { return 0.12 * smooth(1.6, 5.0, t); }
function burstAt(t) { return 0.9 * smooth(4.7, 6.5, t); }

/* ------------------------------------------------------------------ */
/*  DOM                                                                 */
/* ------------------------------------------------------------------ */
var stage = document.getElementById('stage');
var elCountdown = document.getElementById('countdown');
var btnRefire = document.getElementById('btn-refire');
var btnToggle = document.getElementById('btn-toggle');
var iconPlay = document.getElementById('icon-play');
var iconPause = document.getElementById('icon-pause');
var scrubber = document.getElementById('scrubber');
var pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

/* ------------------------------------------------------------------ */
/*  Renderer / scene / camera                                           */
/* ------------------------------------------------------------------ */
var renderer = new THREE.WebGLRenderer({ canvas: stage, antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.outputEncoding = THREE.sRGBEncoding;
renderer.setClearColor(0x000000, 0);
renderer.sortObjects = true;

var scene = new THREE.Scene();
var CAM_FOV = 35, CAM_Z = 9.0;
var camera = new THREE.PerspectiveCamera(CAM_FOV, window.innerWidth / window.innerHeight, 0.1, 60);
camera.position.set(0, 0, CAM_Z);
camera.lookAt(0, 0, 0);

/* Three-point studio lighting (key + fill + dual rims) for standard materials */
function dirLight(hex, i, x, y, z) {
  var l = new THREE.DirectionalLight(hex, i); l.position.set(x, y, z); scene.add(l); return l;
}
dirLight(0xfff4e6, 1.25, 2.5, 3.5, 4.0);     // key, warm
dirLight(0x8a94b0, 0.35, -2.0, 0.5, 3.0);    // fill, dim cool
dirLight(0xd9ecff, 1.6, -3.0, 2.5, -2.5);    // rim 1, cool white
dirLight(0x9ff0ff, 1.15, 3.0, -1.0, -3.0);   // rim 2, cyan
dirLight(0xff80d0, 0.45, -2.0, -2.5, 1.0);   // magenta accent
scene.add(new THREE.AmbientLight(0x3a3f4c, 0.6));

/* Same lights as uniforms for custom shaders (direction toward light, linear colour * intensity) */
function ldir(x, y, z) { return new THREE.Vector3(x, y, z).normalize(); }
var LIGHT_UNIFORMS = {
  uL0: { value: ldir(2.5, 3.5, 4.0) },  uC0: { value: new THREE.Vector3(1.00, 0.95, 0.88).multiplyScalar(1.15) },
  uL1: { value: ldir(-3.0, 2.5, -2.5) }, uC1: { value: new THREE.Vector3(0.82, 0.92, 1.00).multiplyScalar(1.6) },
  uL2: { value: ldir(3.0, -1.0, -3.0) }, uC2: { value: new THREE.Vector3(0.55, 0.93, 1.00).multiplyScalar(1.2) },
  uL3: { value: ldir(-2.0, -2.5, 1.0) }, uC3: { value: new THREE.Vector3(1.00, 0.45, 0.80).multiplyScalar(0.45) }
};

/* Procedural studio environment cube (for the metallic bullet) - six detached canvases */
function envFace(fn) {
  var c = document.createElement('canvas'); c.width = c.height = 64;
  var g = c.getContext('2d'); fn(g, 64); return c;
}
function vgrad(g, s, top, bot) {
  var gr = g.createLinearGradient(0, 0, 0, s); gr.addColorStop(0, top); gr.addColorStop(1, bot);
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
}
function blob(g, s, x, y, r, col) {
  var gr = g.createRadialGradient(x * s, y * s, 0, x * s, y * s, r * s);
  gr.addColorStop(0, col); gr.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
}
var envFaces = [
  envFace(function (g, s) { vgrad(g, s, '#9aa4b8', '#161a22'); blob(g, s, 0.3, 0.5, 0.45, 'rgba(150,230,255,0.75)'); }),  // +X cyan rim
  envFace(function (g, s) { vgrad(g, s, '#a8b0c0', '#1a1c24'); blob(g, s, 0.7, 0.35, 0.5, 'rgba(230,240,255,0.85)'); blob(g, s, 0.4, 0.85, 0.35, 'rgba(255,120,210,0.4)'); }), // -X cool rim + magenta
  envFace(function (g, s) { vgrad(g, s, '#f2f0ea', '#cfd3dc'); blob(g, s, 0.5, 0.5, 0.6, 'rgba(255,255,255,1)'); }),       // +Y softbox
  envFace(function (g, s) { vgrad(g, s, '#141318', '#08080c'); }),                                                       // -Y floor
  envFace(function (g, s) { vgrad(g, s, '#50545e', '#141620'); blob(g, s, 0.72, 0.22, 0.45, 'rgba(255,245,225,0.9)'); }),   // +Z key
  envFace(function (g, s) { vgrad(g, s, '#30343e', '#0c0e14'); blob(g, s, 0.25, 0.4, 0.35, 'rgba(210,230,255,0.8)'); blob(g, s, 0.78, 0.6, 0.35, 'rgba(120,230,255,0.6)'); }) // -Z rims
];
var envTex = new THREE.CubeTexture(envFaces);
envTex.encoding = THREE.sRGBEncoding;
envTex.needsUpdate = true;

/* ------------------------------------------------------------------ */
/*  Shared GLSL                                                         */
/* ------------------------------------------------------------------ */
var GLSL_LIGHTS = [
  'uniform vec3 uL0, uC0, uL1, uC1, uL2, uC2, uL3, uC3;'
].join('\n');
var GLSL_NOISE = [
  'float hash3(vec3 p){ p = fract(p * 0.3183099 + vec3(0.1, 0.2, 0.3)); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }',
  'float vnoise(vec3 x){ vec3 i = floor(x); vec3 f = fract(x); f = f * f * (3.0 - 2.0 * f);',
  '  return mix(mix(mix(hash3(i), hash3(i + vec3(1,0,0)), f.x), mix(hash3(i + vec3(0,1,0)), hash3(i + vec3(1,1,0)), f.x), f.y),',
  '             mix(mix(hash3(i + vec3(0,0,1)), hash3(i + vec3(1,0,1)), f.x), mix(hash3(i + vec3(0,1,1)), hash3(i + vec3(1,1,1)), f.x), f.y), f.z); }'
].join('\n');
var GLSL_TUNNEL = [
  'uniform float uTX0, uTX1, uTR, uTY, uTFlare;',
  'float tshape(float u){',
  '  return 0.42 + 0.58 * pow(max(sin(3.14159265 * u), 0.0), 0.75) + 0.4 * smoothstep(0.22, 0.0, u) + uTFlare * smoothstep(0.78, 1.0, u);',
  '}'
].join('\n');
/* premultiplied-alpha output: colour is computed in linear space, encoded, then premultiplied */
var GLSL_OUT = 'gl_FragColor = vec4(col, a);\n#include <encodings_fragment>\ngl_FragColor.rgb *= gl_FragColor.a;';

