/* ------------------------------------------------------------------ */
/*  Teardrop surface grid with per-vertex tear / impact attributes      */
/* ------------------------------------------------------------------ */
function splitTheta(ph) {
  return THETA_IMP + 0.22 * Math.sin(2 * ph + 0.7) + 0.13 * Math.sin(5 * ph + 2.1) + 0.07 * Math.sin(9 * ph + 4.0);
}
function buildTeardrop(radiusScale, segT, segP) {
  var nv = (segT + 1) * (segP + 1);
  var pos = new Float32Array(nv * 3), nrm = new Float32Array(nv * 3);
  var aD = new Float32Array(nv), aDX = new Float32Array(nv), aSide = new Float32Array(nv), aEdge = new Float32Array(nv);
  var sI = Math.sin(THETA_IMP), cI = Math.cos(THETA_IMP);
