  var p = [0, 0, 0], pa = [0, 0, 0], pb = [0, 0, 0], pc = [0, 0, 0], pd = [0, 0, 0];
  var k = 0;
  for (var i = 0; i <= segT; i++) {
    var th = Math.PI * i / segT;
    for (var j = 0; j <= segP; j++) {
      var ph = 2 * Math.PI * j / segP;
      P(th, ph, p);
      var e = 1e-3, nx, ny, nz;
      if (i === 0) { nx = 0; ny = 1; nz = 0; }
      else if (i === segT) { nx = 0; ny = -1; nz = 0; }
      else {
        P(th - e, ph, pa); P(th + e, ph, pb); P(th, ph - e, pc); P(th, ph + e, pd);
        var tx = pb[0] - pa[0], ty = pb[1] - pa[1], tz = pb[2] - pa[2];
        var qx = pd[0] - pc[0], qy = pd[1] - pc[1], qz = pd[2] - pc[2];
        nx = ty * qz - tz * qy; ny = tz * qx - tx * qz; nz = tx * qy - ty * qx;
        var len = Math.sqrt(nx * nx + ny * ny + nz * nz) || 1; nx /= len; ny /= len; nz /= len;
      }
      pos[k * 3] = p[0]; pos[k * 3 + 1] = p[1]; pos[k * 3 + 2] = p[2];
      nrm[k * 3] = nx; nrm[k * 3 + 1] = ny; nrm[k * 3 + 2] = nz;
      var ux = Math.sin(th) * Math.cos(ph), uy = Math.cos(th), uz = -Math.sin(th) * Math.sin(ph);
      aD[k] = Math.acos(clamp(ux * sI + uy * cI, -1, 1));
      aDX[k] = Math.acos(clamp(-ux * sI + uy * cI, -1, 1));
      var ts = splitTheta(ph);
