/* ------------------------------------------------------------------ */
/*  renderAt(simTime): pure function of simTime -> frame                */
/* ------------------------------------------------------------------ */
function renderAt(t) {
  /* bullet */
  var tip = bulletTipX(t), yaw = 0;
  if (t > T_CONTACT) yaw = 0.07 * Math.sin(4 * (t - T_CONTACT)) * smooth(T_CONTACT, 1.5, t);
  if (t > T_EXIT) yaw += 0.22 * Math.sin(1.6 * (t - T_EXIT)) * (1 - Math.exp(-(t - T_EXIT) * 2));
  bullet.position.set(tip + BULLET_TIP_OFF, Y_IMP, 0);
  bullet.rotation.z = yaw;

  /* latex membrane */
  var dent = 0;
  if (t > T_CONTACT) dent = Math.max(0, XR - tip) * (1 - smooth(T_PUNCT, 1.18, t));
  latexUniforms.uTime.value = t;
  latexUniforms.uDent.value = dent;
  latexUniforms.uTear.value = t > T_PUNCT ? (t - T_PUNCT) * 9.8 : 0;

  /* tether recoil: small swing + hop once the load is released */
  var sw = 0, hop = 0;
  if (t > 1.1) {
    var ts = t - 1.1;
    sw = 0.03 * Math.sin(2 * Math.PI * 0.55 * ts) * Math.exp(-0.25 * ts);
    hop = 0.06 * smooth(1.1, 1.4, t) * (1 - 0.4 * smooth(1.4, 2.5, t));
  }
  tether.rotation.z = sw;
  tether.position.y = PIVOT_Y + hop;

  /* free-standing water mass */
  var W = waterUniforms;
  W.uTime.value = t;
  W.uDent.value = dent;
  W.uHoleIn.value = t > T_PUNCT ? 0.1 + 0.16 * smooth(T_PUNCT, 2.6, t) - 0.1 * smooth(3.9, 5.0, t) : 0;
  W.uCrownIn.value = 0.06 * smooth(T_PUNCT, 1.3, t) * (1 - smooth(3.8, 4.8, t));
  W.uBulge.value = 0.3 * smooth(3.5, T_EXIT, t) * (1 - smooth(T_EXIT, 3.95, t));
  W.uHoleOut.value = t > T_EXIT ? 0.08 + 0.14 * smooth(T_EXIT, 4.4, t) : 0;
  W.uCrownOut.value = 0.07 * smooth(T_EXIT, 3.95, t) * (1 - smooth(4.6, 5.2, t));
  W.uRipple.value = 0.02 * smooth(T_PUNCT, 1.3, t);
  W.uSlosh.value = 0.03 * smooth(1.5, 2.0, t) * Math.sin(2 * Math.PI * 0.7 * (t - 1.5));
  W.uSlump.value = slumpAt(t);
  W.uFall.value = fallAt(t);
  W.uBurst.value = burstAt(t);
  W.uDissolve.value = 1.05 * smooth(4.9, 6.4, t);
  waterBack.visible = waterFront.visible = t < 6.45;

  /* cavitation tunnel between entry hole and bullet */
  var tr = 0.42 * smooth(T_PUNCT, 2.6, t) * (1 - smooth(3.9, 5.0, t));
  var tailX = tip + 0.55, exists = tr > 0.005 && tailX < XR - 0.08;
  tunnelUniforms.uTX0.value = XR - 0.02;
  tunnelUniforms.uTX1.value = exists ? clamp(tailX, XL + 0.02, XR - 0.08) : XR;
  tunnelUniforms.uTR.value = tr;
  tunnelUniforms.uTFlare.value = 0.4 * smooth(T_EXIT, 4.0, t);
  tunnel.visible = exists;
  tunnelMat.uniforms.uTime.value = t;
  partUniforms.uTime.value = t;

  renderer.render(scene, camera);
}

/* ------------------------------------------------------------------ */
/*  Playback state machine: COUNTDOWN / PLAYING / PAUSED / REFIRE_HOLD / ENDED */
/* ------------------------------------------------------------------ */
var state = 'COUNTDOWN';
var simTime = 0, playbackSpeed = 1.0, countdownElapsed = 0, holdElapsed = 0;
var lastTs = null, started = false;

function setIcons(playing) {
  iconPause.style.display = playing ? '' : 'none';
  iconPlay.style.display = playing ? 'none' : '';
  btnToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function hideCountdown() { elCountdown.style.display = 'none'; elCountdown.textContent = ''; }
function showCountdown(txt) {
  if (elCountdown.style.display !== 'block') elCountdown.style.display = 'block';
  if (elCountdown.textContent !== txt) elCountdown.textContent = txt;
}
function advance(dt) {
  simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
  if (simTime >= DURATION) {
    simTime = DURATION;
    scrubber.value = DURATION.toFixed(3);
    state = 'ENDED';
    setIcons(false);
  } else {
    scrubber.value = simTime.toFixed(3);
  }
}
function frame(ts) {
  requestAnimationFrame(frame);
  var dt = 0;
  if (lastTs !== null) dt = Math.min(0.1, Math.max(0, (ts - lastTs) / 1000));
  lastTs = ts;
  if (!started) { started = true; state = 'COUNTDOWN'; countdownElapsed = 0; dt = 0; }
  if (state === 'COUNTDOWN') {
    countdownElapsed += dt;
    if (countdownElapsed >= 3.0) {
      hideCountdown();
      state = 'PLAYING';
      setIcons(true);
      simTime = 0;
      advance(countdownElapsed - 3.0);
    } else {
      showCountdown(countdownElapsed < 1.0 ? '3' : (countdownElapsed < 2.0 ? '2' : '1'));
      simTime = 0;
      if (scrubber.value !== '0') scrubber.value = '0';
    }
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;
    if (holdElapsed >= 1.0) {
      state = 'PLAYING';
      setIcons(true);
      advance(holdElapsed - 1.0);
    }
  } else if (state === 'PLAYING') {
    advance(dt);
  }
  renderAt(simTime);
}

btnToggle.addEventListener('click', function () {
  if (state === 'PLAYING') {
    state = 'PAUSED'; setIcons(false);
  } else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') {
    hideCountdown(); simTime = 0; scrubber.value = '0';
    state = 'PAUSED'; setIcons(false); renderAt(0);
  } else if (state === 'PAUSED') {
    state = 'PLAYING'; setIcons(true);
  } else if (state === 'ENDED') {
    hideCountdown(); simTime = 0; scrubber.value = '0';
    state = 'PLAYING'; setIcons(true); renderAt(0);
  }
});
pills.forEach(function (p) {
  p.addEventListener('click', function () {
    playbackSpeed = parseFloat(p.getAttribute('data-speed'));
    pills.forEach(function (q) {
      var on = q === p;
      q.classList.toggle('is-active', on);
      q.setAttribute('aria-checked', on ? 'true' : 'false');
    });
  });
});
scrubber.addEventListener('input', function () {
  if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') hideCountdown();
  simTime = clamp(parseFloat(scrubber.value) || 0, 0, DURATION);
  state = 'PAUSED'; setIcons(false);
  renderAt(simTime);
});
btnRefire.addEventListener('click', function () {
  hideCountdown();
  countdownElapsed = 0; holdElapsed = 0;
  simTime = 0; scrubber.value = '0';
  setIcons(true);
  renderAt(0);
  state = 'REFIRE_HOLD';
});

function onResize() {
  var w = window.innerWidth, h = window.innerHeight;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  var size = renderer.getDrawingBufferSize(new THREE.Vector2());
  partUniforms.uScale.value = size.y / (2 * Math.tan(CAM_FOV * Math.PI / 360));
  renderAt(simTime);
}
window.addEventListener('resize', onResize);

/* initial resting scene (simTime = 0) renders synchronously; COUNTDOWN starts on the first rAF */
showCountdown('3');
scrubber.value = '0';
setIcons(true);
onResize();
requestAnimationFrame(frame);
})();
</script>
</body>
</html>

