  '  vC = c; vD = aD; vSide = aSide; vEdge = aEdge;',
  '  vec4 wp = modelMatrix * vec4(q, 1.0); vP = wp.xyz;',
  '  vN = normalize(mat3(modelMatrix) * normal);',
