var LATEX_FS = [
  GLSL_LIGHTS,
  'uniform float uTime, uTear;',
  'varying vec3 vN, vP; varying float vD, vSide, vEdge, vC;',
  'const float TP = 1.06;',
  'void latexLight(vec3 L, vec3 C, vec3 n, vec3 v, vec3 base, inout vec3 col, inout vec3 spec){',
  '  float wrap = clamp((dot(n, L) + 0.45) / 1.45, 0.0, 1.0);',
