  '    if (vD < 0.1) discard;',
  '  }',
  '  vec3 n = normalize(vN);',
  '#ifdef FLIP_SIDED',
  '  n = -n;',
  '#endif',
  '  vec3 v = normalize(cameraPosition - vP);',
  '  float ndv = max(dot(n, v), 0.0);',
